use std::process

fn emit(text: string, number: bool, counter: int) -> int {
    let mut n = counter
    if !number {
        print(text)
        return n
    }
    let parts = text.split("\n")
    let total = parts.len()
    let mut i = 0
    for p in parts {
        i += 1
        if i == total && p == "" {
            break
        }
        n += 1
        println("${n:>6}\t${p}")
    }
    n
